function nav(){var sidenav=document.getElementById("sidenav"),marginRight=window.getComputedStyle(sidenav).getPropertyValue("margin-right");sidenav.style.marginRight="-300px"===marginRight||""===marginRight?"0px":"-300px"}function carouselHandler(action,carouselId){var carousel=document.getElementById(carouselId),activeElement=carousel.querySelector(".default.active");if("next"===action){var ProxElement=activeElement.nextElementSibling||carousel.querySelector(".carousel-item:first-child");activeElement.classList.remove("active","slide-fade"),ProxElement.classList.add("active","slide-fade")}else if("prev"===action)if(console.log(activeElement),"home-1"==activeElement.id||"autoras-1"==activeElement.id)ProxElement=activeElement;else{var ProxElement=activeElement.previousElementSibling||carousel.querySelector(".carousel-item:last-child");activeElement.classList.remove("active"),ProxElement.classList.add("active")}}